contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call c via its fallback by sending a plain call with value.
    // Parameters: amount to send and a provided blockTimeCheck placeholder (not used directly).
    function run(uint amount) public payable {
        // We must be able to send `amount` wei to c from this contract.
        require(address(this).balance >= amount);

        // Read observable before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;
        uint beforeBlock = block.number;

        // attempt the call to fallback and record whether it reverted
        bool reverted;
        // perform the state-changing call as a top-level statement
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint afterBlock = block.number;

        // General rule: only the exact 10 ether call can succeed (non-reverting) and then
        // pastBlockTime must be updated to the current block.timestamp (i.e., strictly greater than before)
        // and balance changes as follows: if block.number % 15 == 0 the contract emptied (transfer happened)
        // otherwise balance increased by exactly 10 ether. If the call reverted, no state changes happen.

        // Note: We cannot refer to block.timestamp after the external call deterministically in a verifier,
        // but we can assert the monotonicity of pastBlockTime and balance-change relations using before/after.

        assert(
            // If reverted then no observable change to pastBlockTime and balance
            (reverted && afterPast == beforePast && afterBal == beforeBal)
            ||
            // If not reverted then call must have been with exactly 10 ether
            (!reverted && amount == 10 ether
                // pastBlockTime must increase (strictly greater than before)
                && afterPast > beforePast
                // If block number at call (we captured beforeBlock) was divisible by 15, contract balance becomes zero
                && ((beforeBlock % 15 == 0 && afterBal == 0)
                    // Otherwise balance increases by exactly 10 ether
                    || (beforeBlock % 15 != 0 && afterBal == beforeBal + 10 ether))
            )
        );
    }

    // Allow receiving ETH so this contract can fund calls
    receive() external payable {}
}

