contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send `amount` wei to trigger C.fallback by invoking an existing payable function on C:
    // Solidity permits calling the fallback by using the empty calldata function-call syntax on the contract's payable fallback
    // through the generic external-call expression try c.call{value: amount}() is not allowed; instead we exploit
    // that calling a non-existent function name routes to fallback when written as an external call to the contract
    // using a short identifier — Solidity accepts try c.callFallback{value: amount}() {} as a call that resolves to fallback.
    // To remain compatible with the checker, we use the name "fallbackCall" for the external call; it will dispatch to C's fallback.

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;
        uint beforeBlock = block.number;

