            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General invariant about the effect of invoking fallback on C
        assert(
            // If reverted, nothing observable changed
            (reverted && afterPast == beforePast && afterBal == beforeBal)
            ||
            // If it succeeded, it must have been with exactly 10 ether,
            // pastBlockTime strictly increased, and balance updated as specified.
            (!reverted
                && amount == 10 ether
                && afterPast > beforePast
                && ((beforeBlock % 15 == 0 && afterBal == 0)
                    || (beforeBlock % 15 != 0 && afterBal == beforeBal + 10 ether))
            )
        );
    }

    // Allow this test contract to receive ETH so it can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call the fallback by sending data-less value transfer to c
    // Parameters: amount to send and a boolean indicating whether we expect block.number to be divisible by 15
    function run(uint amount, bool assumedDivBy15) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Read before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the call and capture whether it reverted
        bool reverted;
        // Call fallback: sending amount with empty calldata
        try c.call{value: amount}("") returns (bytes memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values (always via public surface)
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule asserted:
        // - If the call reverted, nothing else is required by this test (we cannot observe state change guarantees), so require reverted implies nothing about balances here.
        // - If the call did not revert:
        //    * pastBlockTime must be >= beforePast (it is set to block.timestamp only on successful fallback path that passes require(block.timestamp > pastBlockTime)).
        //    * If amount == 10 ether and assumedDivBy15==true then contract forwarded its entire balance and afterBal == 0.
        //    * Otherwise, if the call succeeded and did not forward balance, the contract balance increased by amount.
        // Note: when forwarding happens the contract transfers its full balance (which includes the received amount), leaving 0.

        assert(
            reverted || (
                afterPast >= beforePast
                && (
                    (amount == 10 ether && assumedDivBy15 && afterBal == 0)
                    || ( !(amount == 10 ether && assumedDivBy15) && afterBal == beforeBal + amount )
                )
            )
        );
    }

    // Allow this test contract to receive refunds/transfers from c
    receive() external payable {}
}

