    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Observe before state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the call to fallback and capture whether it reverted
        bool reverted;
        try address(c).call{value: amount}("") returns (bytes memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after state
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule:
        // Either the call reverted, or (1) pastBlockTime did not decrease and (2) if the call caused the contract to forward its balance
        // (which happens only when amount == 10 ether and block.number % 15 == 0 and the other requires passed), then afterBal == 0;
        // otherwise if it succeeded and did not forward all balance then the contract's balance increased by exactly amount.
        // We express the possibility of forwarding by checking afterBal == 0 when amount == 10 ether; otherwise balance must be beforeBal + amount.

        assert(
            reverted || (
                afterPast >= beforePast
                && (
                    // If afterBal == 0 then it behaved like a withdraw-on-divisible-by-15; we only require this can happen when amount == 10 ether
                    (afterBal == 0 ? (amount == 10 ether) : (afterBal == beforeBal + amount))
                )
            )
        );
    }

    // Allow this test contract to receive ETH if C forwards balance to it
    receive() external payable {}
}

