        uint beforeBal = address(c).balance;

        // Make the state-changing call to c's fallback as a single top-level statement
        bool success;
        try c.call{value: amount}("") {
            // This branch is unreachable because c.call is not a compiled function call on C;
            // keep to satisfy compiler shape requirements by attempting a direct call via address(c).
        } catch {
            // nop
        }

