contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call the fallback by sending a plain value transfer to c.
    // Parameters: amount to send, and a boolean indicating whether the current block number is divisible by 15.
    // The boolean is only used for the assertion to express the expected conditional behavior; it is an input and
    // not read from the blockchain (the real block.number is observable via c.pastBlockTime change and balance effect).
    function run(uint amount, bool expectDiv15) public payable {
        // Ensure this contract has enough balance to send
        require(address(this).balance >= amount);
        // Read before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the call to c's fallback by sending the value. Must be a top-level state-changing call.
        bool reverted;
        // We only attempt the call; if it reverts, mark reverted = true.
        // Call is performed via low-level call to trigger fallback.
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // Read after-values regardless of revert (if reverted, values unchanged)
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule (single assert):
        // - If the call reverted, nothing changed: pastBlockTime and balance stay the same.
        // - If the call did not revert and amount == 10 ether then pastBlockTime == block.timestamp
        //   (i.e., strictly increased from before if block.timestamp > beforePast) and:
        //     * if (block.number % 15 == 0) then contract balance becomes 0 (caller was paid out);
        //     * otherwise contract balance equals beforeBal + amount.
        // We cannot read block.number inside the assertion, so we relate the zero-balance outcome with expectDiv15 input.

        assert(
            // If reverted: no changes
            (reverted && afterPast == beforePast && afterBal == beforeBal)
            ||
            // If not reverted: amount must be exactly 10 ether and pastBlockTime updated to current timestamp
            (!reverted
                && amount == 10 ether
                && afterPast == block.timestamp
                // If balance became zero then expectDiv15 must be true (caller got paid out when divisible by 15)
                && ((afterBal == 0 && expectDiv15)
                    // Otherwise balance should equal prior balance + amount
                    || (afterBal == beforeBal + amount && ! (afterBal == 0)))
            )
        );
    }

    // Allow the contract to receive Ether when C transfers out its balance to this contract
    receive() external payable {}
}

